/* eslint-disable react/prop-types */
import React, { useEffect, useState, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
  Card,
  Stack,
  Typography,
  TablePagination,
  Popover,
  MenuItem,
  IconButton,
  Button,
  Box,
} from '@mui/material';
import AddBoxIcon from '@mui/icons-material/AddBox';
import GenerateToastConfig from '../../../components/toast-config/GenerateToastConfig';
import { axios } from '../../../utils/axios';
import { updateUrlParams } from '../../../utils/urlUtilis';
import Iconify from '../../../components/iconify';
import Scrollbar from '../../../components/scrollbar';
import { UserListToolbar } from '../../../sections/@dashboard/user';
import { useMyContext } from '../../provider';
import useResponsive from '../../../hooks/useResponsive';
import TanstackTable from '../../../components/tanstackMUItable/TanstackTable';
import DateFormat from '../../../components/dayjsFormat/DateFormat';
import DeleteModal from '../../../components/deleteModal/DeleteModal';
import { IMAGE_URL } from '../../../utils/config';
import TanstackTableV8 from '../../../components/tanstackMUItable/tanstackTableV8';

const ViewSubCategory = () => {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search);
  const navigate = useNavigate();
  const [opens, setOpens] = useState(false);
  const [advSubCategoryList, setAdvSubCategoryList] = useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [search, setsearch] = useState(queryParams.get('search') || '');
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [filters, setFilters] = useState({});
  const [isLoading, setIsLoading] = useState(true);

  // const categoryIds = queryParams.get('categoryIds') || null;
  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm');

  const { categoryIds } = location?.state || { categoryIds: '' };

  useEffect(() => {
    if (categoryIds) {
      fetchData();
    }
  }, [categoryIds, page, rowsPerPage, search, filters])

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let url = `module/ads/admin/subCategory/${categoryIds}?_page=${page}&_limit=${rowsPerPage}`

      // if (search) {
      //   url += `&search=${search}`;
      //   setPage(1);
      // }
      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
        if (value) url += `&${key}=${value}`;
      });

      const response = await axios.get(url);
      if (response.status === 200) {
        setAdvSubCategoryList(response?.data?.data?.subCategories);
        setTotalCount(response?.data?.data?.totalCount ? response?.data?.data?.totalcount : 0);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsLoading(false);
    }
  }

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    const newLimit = parseInt(event.target.value, 10);
    setRowsPerPage(newLimit);
    setPage(1);
  };

  const handleFilterByName = (event) => {
    const filterValue = event.target.value;
    setsearch(filterValue);
    queryParams.set('search', filterValue);
    window.history.pushState(null, '', `?${queryParams.toString()}`);
  };

  const handleOpenAddSubCategory = () => {
    navigate(`/dashboard/advSubCategoryForm`, { state: { categoryId: categoryIds } })
  };

  const backToRoute = () => {
    navigate('/dashboard/category&subcategory');
  }

  const delAdvSubCategory = async () => {
    const advSubCategory = sessionStorage.getItem('rowSubCategoryData');
    try {
      const res = await axios.delete(`module/ads/admin/subcategory/${advSubCategory}`);
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'info');
        setOpens(false);
        fetchData();
      } else {
        GenerateToastConfig(res?.data?.message);
      }
    } catch (error) {
      GenerateToastConfig(error?.response?.data?.message);
    }
  }

  const ActionComponent = (cell) => {
    const value = cell?.getValue();
    const original = cell?.row?.original;
    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    const handleformdata = async (subCategoryId) => {
      navigate(`/dashboard/advSubCategoryForm`, { state: { subCategoryIds: subCategoryId, subCategory: original?.subCategory, description: original?.desc, EditCategoryId: categoryIds } })
    };

    const deleteModal = (ids) => {
      sessionStorage.setItem('rowSubCategoryData', ids);
      setOpens(true);
    };
    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >
          <MenuItem onClick={() => handleformdata(value)}>
            <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
          </MenuItem>
          <MenuItem onClick={() => deleteModal(value)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>
        </Popover>
      </>
    )
  }

  const columns = [
    {
      header: i18?.ACCOUNTSTITLE?.SUBCATEGORY || 'Sub-Category',
      id: 'subCategory',
      accessorKey: 'subCategory',
      showFilter: false,
      cell: ({ row }) => <span>{row?.original?.subCategory || "---"}</span>
    },
    {
      header: i18?.ACCOUNTSTITLE?.DESCRIPTION || 'Description',
      id: 'desc',
      accessorKey: 'desc',
      cell: ({ row }) => <span>{row?.original?.desc || "---"}</span>
    },
    {
      header: i18?.ACCOUNTSTITLE?.ACTION || 'Action',
      id: 'action',
      accessorKey: '_id',
      cell: ActionComponent,
    },
  ];

  // const columns = useMemo(() => COLUMNS, []);
  // const data = React.useMemo(() => advSubCategoryList?.map((advSubCategoryData) => {
  //   return {
  //     subCategory: advSubCategoryData?.subCategory,
  //     desc: advSubCategoryData?.desc,
  //     action: advSubCategoryData?._id,
  //   }
  // }), [advSubCategoryList])

  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };

  return (
    <>
      <Helmet>
        <title> View SubCategory | Admin panel </title>
      </Helmet>
      {isMobile && <Stack direction='row' alignItems="center" style={{ marginBottom: "30px" }} justifyContent="space-between">
        <Typography variant="h4" gutterBottom>
          {i18?.ACCOUNTSTITLE?.SUBCATEGORYLIST || "Sub-Category List"}
        </Typography>
        <Button sx={{
          padding: "9px 28px"
        }} variant="contained" onClick={handleOpenAddSubCategory} startIcon={<AddBoxIcon />}>
          {i18?.ACCOUNTSTITLE?.ADD_SUBCATEGORY || "Add Sub-Category"}
        </Button>
      </Stack>}
      {!isMobile && <Stack direction='row' alignItems="center" justifyContent="space-between">
        <Stack direction={'row'} alignItems="center" >
          <Box
            sx={{
              width: '37px',
              height: '37px',
              background: '#FF5A60',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              borderRadius: '50%',
              cursor: 'pointer',
              marginRight: '10px',
              marginBottom: '8px',
            }}
            onClick={backToRoute}
          >
            <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
          </Box>
          <Typography variant="h4" gutterBottom>
            {i18?.ACCOUNTSTITLE?.SUBCATEGORYLIST || "Sub-Category List"}
          </Typography>
        </Stack>
        <Stack direction='row' alignItems="center" >
          <UserListToolbar
            // numSelected={selected.length}
            // filterName={filterName}
            onFilterName={handleFilterByName}
            search={search}
            setsearch={setsearch}
          />
          <Button sx={{
            padding: "9px 28px"
          }} variant="contained" onClick={handleOpenAddSubCategory} startIcon={<AddBoxIcon />}>
            {i18?.ACCOUNTSTITLE?.ADD_SUBCATEGORY || "Add Sub-Category"}
          </Button>
        </Stack>
      </Stack>}

      <Card sx={{ padding: '0px 0px', margin: '0px 0px', overflowX: 'auto' }}>
        {isMobile && <UserListToolbar
          // numSelected={selected.length}
          // filterName={filterName}
          onFilterName={handleFilterByName}
          search={search}
          setsearch={setsearch}
        />}

        <Scrollbar>
          {/* <TanstackTable data={data} columns={columns} /> */}
          <TanstackTableV8
            data={advSubCategoryList}
            columns={columns}
            filters={filters}
            isLoading={isLoading}
            onFilterChange={handleFilterChange}
          />
        </Scrollbar>
      </Card>
      <DeleteModal
        isDeleteOpen={opens}
        handleClose={() => setOpens(false)}
        handleDelete={delAdvSubCategory}
      />
    </>
  )
}

export default ViewSubCategory
